:deep(.modal-container) {
	width: calc(100vw - 120px) !important;
	height: calc(100vh - 120px) !important;
	max-width: 600px !important;
	max-height: 500px !important;
}

.modal-content {
	display: flex;
	box-sizing: border-box;
	width: 100%;
	height: 100%;
	flex-direction: column;
	padding: calc(var(--default-grid-baseline) * 4);
}

.crumbs {
	display: inline-flex;
	padding-inline-end: 0;
	flex-wrap: wrap;

	.level {
		display: inline-flex;
		height: 44px;
		min-width: 0px;
		flex: 0 0 auto;
		order: 1;
		padding-inline-end: calc(var(--default-grid-baseline) * 2);
		background-position: right center;
		background-size: auto 24px;
		margin-top: calc(var(--default-grid-baseline) * -2.5);
	}

	a {
		position: relative;
		padding: calc(var(--default-grid-baseline) * 3);
		opacity: 0.5;
		text-overflow: ellipsis;
		white-space: nowrap;
		overflow: hidden;
		flex: 0 0 auto;
		min-width: 0px;
		max-width: 200px;

		&:hover {
			opacity: 0.7;
		}
	}

	a.icon-home {
		width: 0px;
		background-position: left center;
	}
}

.mailbox-list {
	display: inline-block;
	width: 100%;
	height: 100%;
	overflow-y: auto;
	flex: 1;

	li {
		display: flex;
		cursor: pointer;

		&:hover {
			background-color: var(--color-background-hover);
		}

		&:not(:last-child) {
			border-bottom: var(--border-width-input) solid var(--color-border);
		}
	}

	h2 {
		width: 100%;
		color: var(--color-text-maxcontrast);
		text-align: center;
		margin-top: 80px;
		opacity: 0.4;
		background-size: 64px;
		height: 64px;
	}

	.mailbox-icon {
		width: 24px;
		height: 24px;
		padding: calc(var(--default-grid-baseline) * 3);
		opacity: 0.9;
		background-size: 24px;
	}

	.mailbox-title {
		padding: calc(var(--default-grid-baseline) * 3) calc(var(--default-grid-baseline) * 3) calc(var(--default-grid-baseline) * 3) 0;
		flex: 1;
		overflow: hidden;
		white-space: nowrap;
		text-overflow: ellipsis;
	}
}

.buttons {
	display: flex;
	justify-content: flex-end;
	padding-top: calc(var(--default-grid-baseline) * 2);

	.spinner {
		margin-inline-end: var(--default-grid-baseline);
	}
}

.material-design-icon {
	opacity: .7;
	margin-inline-end: calc(var(--default-grid-baseline) * 1.5);
}
