<script>
import CKEditor from '@ckeditor/ckeditor5-vue2'
import { getLanguage } from '@nextcloud/l10n'
import { emojiAddRecent, emojiSearch } from '@nextcloud/vue'
import {
	Alignment,
	Base64UploadAdapter,
	BlockQuote,
	Bold,
	ClassicEditor,
	DropdownView,
