<template>
	<form id="sieve-form">
		<p>
			{{ t('yoomail', 'Sieve is a powerful language for writing filters for your mailbox. You can manage the sieve scripts in Mail if your email service supports it. Sieve is also required to use Autoresponder and Filters.') }}
		</p>
		<p>
			<NcCheckboxRadioSwitch v-model="sieveConfig.sieveEnabled">
				{{ t('yoomail', 'Enable sieve filter') }}
			</NcCheckboxRadioSwitch>
		</p>
		<div v-if="sieveConfig.sieveEnabled">
			<NcTextField v-model="sieveConfig.sieveHost" :label="t('yoomail', 'Sieve host')" />
			<h4>{{ t('yoomail', 'Sieve security') }}</h4>
			<div class="flex-row">
				<ButtonVue
					:pressed="sieveConfig.sieveSslMode === 'none'"
					@click="updateSslMode('none')">
					{{ t('yoomail', 'None') }}
				</ButtonVue>
				<ButtonVue
					:pressed="sieveConfig.sieveSslMode === 'ssl'"
					@click="updateSslMode('ssl')">
					{{ t('yoomail', 'SSL/TLS') }}
				</ButtonVue>
				<ButtonVue
					:pressed="sieveConfig.sieveSslMode === 'tls'"
					@click="updateSslMode('tls')">
					{{ t('yoomail', 'STARTTLS') }}
				</ButtonVue>
			</div>
			<NcTextField v-model="sieveConfig.sievePort" :label="t('yoomail', 'Sieve Port')" />
			<h4>{{ t('yoomail', 'Sieve credentials') }}</h4>
			<div class="flex-row">
				<ButtonVue
					:pressed="useImapCredentials"
					@click="updateCredentials(true)">
					{{ t('yoomail', 'IMAP credentials') }}
				</ButtonVue>
				<ButtonVue
					:pressed="!useImapCredentials"
					@click="updateCredentials(false)">
					{{ t('yoomail', 'Custom') }}
				</ButtonVue>
			</div>
			<p v-if="!useImapCredentials" class="custom">
				<NcTextField v-model="sieveConfig.sieveUser" :label="t('yoomail', 'Sieve User')" />
				<NcPasswordField v-model="sieveConfig.sievePassword" :label="t('yoomail', 'Sieve Password')" />
			</p>
		</div>
		<slot name="feedback" />
		<p v-if="errorMessage">
			{{ t('yoomail', 'Oh snap!') }}
			{{ errorMessage }}
		</p>
		<ButtonVue
			type="primary"
			:disabled="loading"
			:aria-label="t('yoomail', 'Save sieve settings')"
			@click.prevent="onSubmit">
			{{ t('yoomail', 'Save sieve settings') }}
		</ButtonVue>
	</form>
</template>

<script>
import { NcButton as ButtonVue, NcCheckboxRadioSwitch, NcPasswordField, NcTextField } from '@nextcloud/vue'
import { mapStores } from 'pinia'
import useMainStore from '../store/mainStore.js'

export default {
	name: 'SieveAccountForm',
	components: {
		ButtonVue,
		NcTextField,
		NcPasswordField,
		NcCheckboxRadioSwitch,
	},

	props: {
		account: {
			type: Object,
			required: true,
		},
	},

	data() {
		return {
			sieveConfig: {
				sieveEnabled: this.account.sieveEnabled,
				sieveHost: this.account.sieveHost || this.account.imapHost,
				sievePort: this.account.sievePort || 4190,
				sieveUser: this.account.sieveUser || '',
				sievePassword: '',
				sieveSslMode: this.account.sieveSslMode || 'tls',
			},

			loading: false,
			useImapCredentials: !this.account.sieveUser,
			errorMessage: '',
		}
	},

	computed: {
		...mapStores(useMainStore),
	},

	methods: {
		updateSslMode(value) {
			this.sieveConfig.sieveSslMode = value
		},

		updateCredentials(value) {
			this.useImapCredentials = value
		},

		async onSubmit() {
			this.loading = true
			this.errorMessage = ''

			// empty user and password => use imap credentials
			if (this.sieveConfig.sieveUser === '' && this.sieveConfig.sievePassword === '') {
				this.useImapCredentials = true
			}

			// clear user and password if imap credentials are used
			if (this.useImapCredentials) {
				this.sieveConfig.sieveUser = ''
				this.sieveConfig.sievePassword = ''
			}

			try {
				await this.mainStore.updateSieveAccount({
					account: this.account,
					data: this.sieveConfig,
				})
				if (this.sieveConfig.sieveEnabled) {
					await this.mainStore.fetchActiveSieveScript({
						accountId: this.account.id,
					})
				}
			} catch (error) {
				this.errorMessage = error.message
			}

			this.loading = false
		},
	},
}
</script>

